import{_ as t,o as a,c as o,ag as r}from"./chunks/framework.CZxGLIO_.js";const f=JSON.parse('{"title":"后台初始化与日常管理","description":"配置站点、邮件、分类、权限和第三方登录，完成上线前验证。","frontmatter":{"title":"后台初始化与日常管理","description":"配置站点、邮件、分类、权限和第三方登录，完成上线前验证。"},"headers":[],"relativePath":"docs/gooseforum/administration/index.md","filePath":"docs/gooseforum/administration/index.md"}'),d={name:"docs/gooseforum/administration/index.md"};function i(n,e,c,l,s,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="后台初始化与日常管理" tabindex="-1">后台初始化与日常管理 <a class="header-anchor" href="#后台初始化与日常管理" aria-label="Permalink to &quot;后台初始化与日常管理&quot;">​</a></h1><p>完成 <a href="./../installation/">首次启动</a> 后，以管理员身份进入后台。推荐先确定站点身份与访问规则，再开放注册。</p><h2 id="站点信息与公告" tabindex="-1">站点信息与公告 <a class="header-anchor" href="#站点信息与公告" aria-label="Permalink to &quot;站点信息与公告&quot;">​</a></h2><p>在「设置 → 站点信息」（<code>/admin/settings/site-info</code>）维护名称、公开 URL、联系邮箱、Logo、描述和外部链接。公开 URL 应与访问域名及 <code>config.toml</code> 的 <code>server.url</code> 保持一致。</p><p>「设置 → 公告」用于开启和编辑站点公告；「设置 → 发帖」维护标题和正文长度、新用户冷却、每日主题上限、附件开关、数量、大小及扩展名规则。建议先用普通账号验证实际效果，避免只从管理员视角检查权限。</p><h2 id="邮件先测试-再开启强制验证" tabindex="-1">邮件先测试，再开启强制验证 <a class="header-anchor" href="#邮件先测试-再开启强制验证" aria-label="Permalink to &quot;邮件先测试，再开启强制验证&quot;">​</a></h2><ol><li>在「设置 → 邮件」（<code>/admin/settings/mail</code>）填写 SMTP 主机、端口、账号、密码或授权码、SSL 和发件人信息。</li><li>使用测试邮件功能检查当前表单值，并到收件箱确认送达；测试可以使用尚未保存的值，测试成功后仍需保存配置。</li><li>在「设置 → 安全」配置注册、邮箱验证和允许注册的邮箱域名。</li><li>用一个新邮箱走完注册、验证、登录和重置密码流程。</li></ol><p>需要本站发送验证邮件的新账号，在 SMTP 未配置时会被拒绝创建。SMTP 接受邮件也不代表最终送达，需要同时检查垃圾邮件、发件服务的退信与发送记录。</p><h2 id="分类、可见性与权限" tabindex="-1">分类、可见性与权限 <a class="header-anchor" href="#分类、可见性与权限" aria-label="Permalink to &quot;分类、可见性与权限&quot;">​</a></h2><p>在 <code>/admin/categories</code> 创建分类并设置名称、标识、描述、颜色和排序。分类是否公开由 <code>everyone</code> 权限组是否可读决定；受限分类需要明确允许访问的组。</p><table tabindex="0"><thead><tr><th>管理事项</th><th>使用入口</th><th>核对重点</th></tr></thead><tbody><tr><td>分类内容与版主</td><td>分类管理</td><td>版主可按用户名或用户 ID 查找</td></tr><tr><td>分类访问范围</td><td>分类访问设置</td><td>保留至少一个有效可读组，使用游客和普通账号验证</td></tr><tr><td>后台管理权限</td><td><code>/admin/roles</code></td><td>按职责分配权限；完整管理员拥有更广权限</td></tr><tr><td>发帖与附件限制</td><td><code>/admin/settings/posting</code></td><td>检查新用户、普通用户的实际限制</td></tr></tbody></table><p>主题管理员可编辑分类和管理版主；角色管理员可管理分类访问权限，但不因此获得分类编辑权限。存在多分类主题时，公开分类转为受限分类可能被阻止，应先处理关联主题，不能把保存失败当作已经生效。</p><h2 id="第三方登录与本站-oidc" tabindex="-1">第三方登录与本站 OIDC <a class="header-anchor" href="#第三方登录与本站-oidc" aria-label="Permalink to &quot;第三方登录与本站 OIDC&quot;">​</a></h2><p>这两个入口解决不同问题：</p><ul><li><strong>OAuth 登录</strong>（<code>/admin/settings/oauth</code>）：让用户使用 GitHub、Google、Discord 或自定义 OIDC 身份登录本站。</li><li><strong>OIDC 提供方</strong>（<code>/admin/settings/oidc-provider</code>）：让其他应用使用 GooseForum 账号登录。</li></ul><p>配置第三方登录时，复制后台显示的回调地址到提供商控制台，填写 Client ID 和 Secret 后启用。修改域名或 HTTPS 配置后重新核对回调地址；不要凭经验拼接路径。</p><p>第三方邮箱与现有账号冲突时不会自动绑定。已有用户应先登录原账号，再主动绑定第三方身份。关闭注册后，已有账号仍可登录和绑定，但首次创建第三方账号同样受注册政策限制。</p><h2 id="上线验收" tabindex="-1">上线验收 <a class="header-anchor" href="#上线验收" aria-label="Permalink to &quot;上线验收&quot;">​</a></h2><p>以游客、普通用户、管理员三个视角检查：首页与分类可见性、注册验证、登录退出、主题与回复、附件访问、举报或管理入口。使用站点真实 HTTPS 域名测试第三方回调和邮件链接。</p><p>接下来阅读 <a href="./../security/">账号安全</a> 和 <a href="./../maintenance/">备份与升级</a>。</p><hr><p>核对日期：2026-11-15；依据当前源码：<a href="https://github.com/leancodebox/GooseForum/blob/3044207dea0a9fd5c878406eb0aa094f5798f0ff/docs/react-migration/admin-mail-security.md" target="_blank" rel="noreferrer">后台设置</a> · <a href="https://github.com/leancodebox/GooseForum/blob/3044207dea0a9fd5c878406eb0aa094f5798f0ff/docs/react-migration/admin-categories.md" target="_blank" rel="noreferrer">分类权限</a> · <a href="https://github.com/leancodebox/GooseForum/blob/3044207dea0a9fd5c878406eb0aa094f5798f0ff/docs/react-migration/admin-oauth-oidc.md" target="_blank" rel="noreferrer">OAuth / OIDC</a> · <a href="https://github.com/leancodebox/GooseForum/blob/3044207dea0a9fd5c878406eb0aa094f5798f0ff/docs/registration-controls.md" target="_blank" rel="noreferrer">注册政策</a>。</p>',22)])])}const b=t(d,[["render",i]]);export{f as __pageData,b as default};
